from .syslog_entry import SyslogEntry


class UteSyslogEntry(SyslogEntry):
    """
    Log entry in syslog file captured by ute_syslog library.
    """

    def __init__(self, btslog_timestamp, btslog_seq_nr, source_ip_addr, **kwargs):
        super(UteSyslogEntry, self).__init__(**kwargs)
        self.btslog_timestamp = btslog_timestamp
        self.btslog_seq_nr = btslog_seq_nr
        self.source_ip_addr = source_ip_addr
